class Solution { public int minimumMountainRemovals(int[] nums){int n=nums.length;int[] increasing=new int[n],decreasing=new int[n];Arrays.fill(increasing,1);Arrays.fill(decreasing,1);for(int i=0;i<n;i++)for(int j=0;j<i;j++)if(nums[j]<nums[i])increasing[i]=Math.max(increasing[i],increasing[j]+1);for(int i=n-1;i>=0;i--)for(int j=n-1;j>i;j--)if(nums[j]<nums[i])decreasing[i]=Math.max(decreasing[i],decreasing[j]+1);int longest=0;for(int i=1;i<n-1;i++)if(increasing[i]>1&&decreasing[i]>1)longest=Math.max(longest,increasing[i]+decreasing[i]-1);return n-longest;} }
